<!--vbase-->
<template>
  <div class="container page-height-limit">
    <div>{{ $t('it_view_text') }}</div>
    <div class="row q-col-gutter-md">
      <div class="col-12 col-md-6">
        <q-card flat bordered class="q-pa-md" id="chart-container101">
          <div id="chart101"></div>
        </q-card>
      </div>
      <div class="col-12 col-md-6">
        <q-card flat bordered class="q-pa-md" id="chart-container102">
          <div id="chart102"></div>
        </q-card>
      </div>
    </div>

    <div class="row q-col-gutter-md mt-15">
      <div class="col-12 col-md-12">
        <q-card flat bordered class="q-pa-md" id="chart-container103">
          <div id="chart103"></div>
        </q-card>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { ApiExceptions } from 'src/exceptions/index';
import { useDropdownStore } from 'src/store/main';
import ApexCharts from 'apexcharts';
import type { dynamicObj } from 'src/pages/assets';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import cache from 'src/utils/cache';
import { Dark } from 'quasar';
import { performanceLogsApiService } from 'src/services';
import dateUtils from 'src/utils/date';
import helperMixin from 'src/mixins/helperMixin.js';
import date from 'src/utils/date';
import { colorMapForCharts } from 'src/constants';
export default defineComponent({
  props: ['tab'],
  components: {},
  mixins: [displayFieldLabel, cache, dateUtils, helperMixin, date],
  data() {
    return {
      chartData: ref([] as any),
      chart: ref(null as any),
      selected_micro_service: ref(null),
      darkMode: false,
      chartCount: 0,
      itEventHandler: null as ((event: any) => void) | null,
      colorMapForCharts,
    };
  },
  mounted() {
    this.initView();
    if (Boolean(Dark.isActive) == true) {
      this.darkMode = true;
    } else {
      this.darkMode = false;
    }
    this.itEventHandler = this.applyFilterOnChart.bind(this);
    document.addEventListener('apply_filter_on_it_view', this.itEventHandler);
  },
  beforeUnmount() {
    if (this.itEventHandler) {
      document.removeEventListener(
        'apply_filter_on_it_view',
        this.itEventHandler,
      );
    }
  },
  methods: {
    initView() {
      this.prepareAndRenderChart({});
    },
    //Call Data Apis and Render Chart
    async prepareAndRenderChart(paramsData: any) {
      this.showLoading();
      await this.prepareServiceMetricsSummary(paramsData);
      await this.prepareProcessFrequencyData(paramsData);
    },
    //Clear Chart containers
    clearChart() {
      for (let i = 1; i <= this.chartCount; i++) {
        var chart = document.getElementById('chart10' + i);
        if (chart) {
          chart.remove();
        }
        var chart_container = document.getElementById('chart-container10' + i);
        if (chart_container) {
          chart_container.innerHTML = '<div id="chart10' + i + '"></div>';
        }
      }
      this.chartCount = 0;
    },
    //Binded function to filters in parent components
    applyFilterOnChart(event: any) {
      this.clearChart();
      if (event.detail) {
        this.selected_micro_service = event.detail.selected_micro_service;
        this.prepareAndRenderChart(event.detail);
      } else {
        this.clearFilterOnChart();
        this.prepareAndRenderChart({});
      }
    },
    //Function to render Process Frequency Data
    async prepareProcessFrequencyData(paramsData: any) {
      try {
        const response =
          await performanceLogsApiService.getProcessFrequency(paramsData);
        if (response.success == false) {
          throw response;
        }

        let formattedLabels = response.labels.map((label: string) =>
          this.formatDateAccordingToPreference(label, true),
        );

        //Process each data to cretae a separate series
        const dataBloc: {
          name: string;
          data: any;
          visible: any;
          showInLegend: any;
        }[] = [];
        let colors: string[] = [];
        Object.entries(response.service_counts).forEach((data: any) => {
          const isSelected =
            !this.selected_micro_service ||
            data[0] === this.selected_micro_service;
          dataBloc.push({
            name: this.$t(data[0]),
            data: isSelected ? data[1] : [],
            visible: isSelected,
            showInLegend: isSelected,
          });
          colors.push((colorMapForCharts as Record<string, string>)[data[0]]);
        });
        this.chartData['process_frequency'] = {
          data: dataBloc,
          labels: formattedLabels,
        };

        this.chartData['process_frequency'].colors = colors;
        this.chartData['process_frequency'].title =
          this.$t('process_frequency');
        this.renderChart(
          this.chartData['process_frequency'],
          'bar',
          2,
          true,
          true,
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      }
    },
    //Function to render Service Metrics Data
    async prepareServiceMetricsSummary(paramsData: any) {
      try {
        const response =
          await performanceLogsApiService.getServiceMetricsSummary(paramsData);
        if (response.success == false) {
          throw response;
        }

        //Set microservice list to be used as filter
        this.microservice_list = response.avg_duration.labels.map(
          (label: string) => {
            return {
              value: label,
              valueStr: this.$t(label),
              label: this.$t(label),
            };
          },
        );

        //Process data to generate series and handle dynamic display based on service filter
        const dataBloc: {
          name: string;
          data: any;
          visible: any;
          showInLegend: any;
        }[] = [];
        let colors: string[] = [];
        Object.entries(response.avg_duration.data).forEach((value, index) => {
          const labelKey = response.avg_duration.labels[index];
          const isSelected =
            !this.selected_micro_service ||
            labelKey === this.selected_micro_service;
          const dataArray = Array.from(
            { length: response.avg_duration.data.length },
            (_, i) => (i === index ? value[1] : 0),
          );
          dataBloc.push({
            name: this.$t(response.avg_duration.labels[index]),
            data: isSelected ? dataArray : [],
            visible: isSelected,
            showInLegend: isSelected,
          });
          colors.push(
            (colorMapForCharts as Record<string, string>)[
              response.avg_duration.labels[index]
            ],
          );
        });

        this.chartData['average_duration'] = {
          data: dataBloc,
          labels: response.avg_duration.labels,
        };
        const formattedLabels: string[] = [];
        response.avg_duration.labels.forEach((labelString: string) => {
          formattedLabels.push(this.$t(labelString));
        });
        this.chartData['average_duration'].colors = colors;
        this.chartData['average_duration'].labels = formattedLabels;
        this.chartData['average_duration'].title = this.$t('average_duration');
        this.renderChart(
          this.chartData['average_duration'],
          'bar',
          1,
          true,
          false,
        );

        //Process Service Min and Max data for two column bar chart
        this.chartData['service_min_max'] = {};
        const categories = [];
        const minValues = [];
        const maxValues = [];
        for (const [key, value] of Object.entries(
          response.service_execution.data[0].service_min_max,
        )) {
          const val = value as { min: number; max: number };
          categories.push(this.$t(key));
          minValues.push(val.min);
          maxValues.push(val.max);
        }
        this.chartData['service_min_max'] = {
          data: [
            { name: this.$t('minimun'), data: minValues },
            { name: this.$t('maximum'), data: maxValues },
          ],
          labels: categories,
        };
        this.chartData['service_min_max'].title = this.$t('service_summary');
        this.renderChart(
          this.chartData['service_min_max'],
          'bar',
          3,
          true,
          false,
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      }
    },
    //Render Chart with required options
    renderChart(
      chart_data: any,
      chart_type: string,
      chart_index: number,
      isMultiChart = false,
      isStacked = false,
    ) {
      try {
        if (!this.chartData) {
          return;
        }
        this.chartCount += 1;
        var options = {
          chart: {
            type: chart_type,
            stacked: isStacked ? true : false,
            height: 400,
          },
          theme: {
            mode: this.darkMode ? 'dark' : 'light',
          },
          plotOptions: {
            bar: {
              horizontal: false,
            },
          },
          xaxis: {
            categories: chart_data.labels,
            labels: {
              style: {
                colors: this.darkMode ? '#FFFFFF' : '#000000',
              },
            },
          },
          yaxis: {
            title: {
              text: !isStacked ? this.$t('time_yaxis_label') : '',
            },
            labels: {
              formatter: (val: number) => {
                return isStacked
                  ? Math.round(val)
                  : this.formatSecondsToHoursMinutes(Number(val.toFixed(2)));
              },
            },
          },
          dataLabels: {
            enabled: true,
            formatter: (val: number) => {
              return val === 0
                ? ''
                : isStacked
                  ? Math.round(val)
                  : this.formatSecondsToHoursMinutes(Number(val.toFixed(2)));
            },
            style: {
              fontWeight: 300,
              colors: this.darkMode ? ['#FFFFFF'] : ['#000000'], //D3D3D3
            },
          },
          series: chart_data.data,
          title: {
            text: chart_data.title,
          },
          labels: chart_data.labels,
          tooltip: {
            y: {
              formatter: (val: number) =>
                isStacked
                  ? Math.round(val)
                  : this.formatSecondsToHoursMinutes(Number(val.toFixed(2))),
            },
          },
          legend: {
            show: true,
            horizontalAlign: 'center',
          },
          colors: chart_data.colors,
        };

        if (document.querySelector('#chart10' + chart_index) !== null) {
          this.chart = new ApexCharts(
            document.querySelector('#chart10' + chart_index),
            options,
          );
          this.chart.render();
          this.hideLoading();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      }
    },
    clearFilterOnChart() {
      this.selected_micro_service = null;
    },
  },

  setup() {
    const dropdown_store = useDropdownStore();
    const { microservice_list } = storeToRefs(dropdown_store);

    return {
      microservice_list,
    };
  },
});
</script>
