<!--vbase-->
<template>
  <!-- <SubHeader name='performance_metrics' :label="$t('performance_metrics')" :display_help_link="false"/> -->
  <div class="container page-height-limit">
    <div class="row q-mt-md q-mb-md grid-main"></div>
    <div class="row mt-20 mb-25 q-gutter-x-sm">
      <q-select
        outlined
        dense
        v-model="selected_date_range"
        :options="[
          {
            label: $t('last_7_days'),
            value: '7',
          },
          {
            label: $t('last_30_days'),
            value: '30',
          },
          {
            label: $t('select_time_range'),
            value: 'custom',
          },
        ]"
        @update:model-value="dateRangeOptionSelected"
        class="white-inputs"
        :label="$t('time_unit')"
        style="width: 20%"
        emit-value
        map-options
      >
        <template v-slot:selected>
          <template v-if="selected_date_range === 'custom'">
            {{ board_date }}
          </template>
          <template v-else>{{ $t(board_date) }}</template>
        </template>
        <template v-slot:append>
          <q-icon name="event" class="cursor-pointer" @click.stop.prevent>
            <q-tooltip>Select Date-Range</q-tooltip>
            <q-popup-proxy
              cover
              v-model="show_calender"
              transition-show="scale"
              transition-hide="scale"
              ref="qDateProxy"
            >
              <q-date v-model="custom_date_range" minimal range>
                <div class="row items-center justify-end q-gutter-sm">
                  <f-btn
                    :label="$t('close')"
                    appearance="negative-tertiary"
                    v-close-popup
                  />
                  <f-btn
                    label="Ok"
                    appearance="tertiary"
                    @click="dateRangeCalenderSelected"
                    v-close-popup
                  />
                </div>
              </q-date>
            </q-popup-proxy>
          </q-icon>
        </template>
      </q-select>

      <q-select
        outlined
        dense
        v-model="selected_micro_service"
        :options="microservice_list"
        class="white-inputs"
        :label="$t('microservice')"
        style="width: 20%"
        emit-value
        map-options
        v-if="tab === 'it_view'"
      />

      <q-select
        outlined
        dense
        v-model="selected_time_group"
        :options="time_group_list"
        class="white-inputs"
        :label="$t('time_group_frequency')"
        style="width: 20%"
        emit-value
        map-options
        v-if="tab === 'it_view'"
      />
      <f-btn @click="applyFilterOnChart" :label="$t('filter')">
        <q-tooltip> {{ $t('filter') }} </q-tooltip>
      </f-btn>
      <f-btn @click="clearFilterOnChart" :label="$t('clear')">
        <q-tooltip> {{ $t('clear') }} </q-tooltip>
      </f-btn>
    </div>

    <div class="row justify-start">
      <q-tabs
        v-model="tab"
        class="text-primary"
        active-color="primary"
        indicator-color="primary"
      >
        <q-tab name="business_view">{{ $t('business_view') }}</q-tab>
        <q-tab name="it_view">{{ $t('it_view') }}</q-tab>
      </q-tabs>
    </div>

    <q-tab-panels v-model="tab" animated>
      <q-tab-panel name="business_view">
        <BusinessView :tab="tab" />
      </q-tab-panel>
      <q-tab-panel name="it_view">
        <ITView :tab="tab" />
      </q-tab-panel>
    </q-tab-panels>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useDropdownStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { objLen } from 'src/utils/general';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import cache from 'src/utils/cache';
import { Dark } from 'quasar';
import { date } from 'quasar';
import BusinessView from './BusinessView.vue';
import ITView from './ITView.vue';

export default defineComponent({
  components: {
    BusinessView,
    ITView,
  },
  mixins: [displayFieldLabel, cache],
  beforeRouteLeave: function (to: any, from: any, next: any) {
    next();
  },
  watch: {
    selected_date_range: {
      handler: function (newVal, oldVal) {
        this.selected_date_range_prev = oldVal;
      },
    },
  },
  data() {
    return {
      saved_requests: ref([] as any[]),
      chartData: ref([] as any),
      chart: ref(null as any),
      selected_user: ref(null),
      selected_document_type: ref(null),
      selected_document_status: ref(null),
      selected_micro_service: ref(null),
      darkMode: false,
      chartCount: 0,
      startIndex: 3,
      donutCount: 0,
      tab: 'business_view',
      filterParams: {},
      time_group_list: [
        {
          value: '1 hour',
          valueStr: this.$t('one_hour'),
          label: this.$t('one_hour'),
        },
        {
          value: '1 day',
          valueStr: this.$t('one_day'),
          label: this.$t('one_day'),
        },
        {
          value: '1 week',
          valueStr: this.$t('one_week'),
          label: this.$t('one_week'),
        },
        {
          value: '1 month',
          valueStr: this.$t('one_month'),
          label: this.$t('one_month'),
        },
      ],
      selected_time_group: ref(''),
    };
  },
  computed: {
    //Function to show seleted data in date field
    board_date: function () {
      if (this.selected_date_range === 'custom_reselect') {
        return this.custom_date_range.from + ' - ' + this.custom_date_range.to;
      }

      return this.selected_date_range
        ? 'pages.report.' + this.selected_date_range
        : '';
    },
  },
  mounted() {
    if (Boolean(Dark.isActive) == true) {
      this.darkMode = true;
    } else {
      this.darkMode = false;
    }
  },

  methods: {
    //Handle Custom Date Selection
    dateRangeOptionSelected() {
      if (this.selected_date_range === 'custom') {
        this.selected_date_range = this.selected_date_range_prev;
        this.show_calender = true;
        return;
      }
      this.setDate();
    },
    setDate() {
      const numberOfDaysToAdd = Number(this.selected_date_range);
      const current_date = new Date();
      const end_date = new Date();
      const start = current_date.setDate(
        current_date.getDate() - numberOfDaysToAdd,
      );

      const startOfMonth = date.formatDate(start, 'YYYY/MM/DD');
      const endOfMonth = date.formatDate(end_date, 'YYYY/MM/DD');
      this.custom_date_range = { from: startOfMonth, to: endOfMonth };
      this.dropdown_store.custom_date_range = this.custom_date_range;
    },
    dateRangeCalenderSelected() {
      this.custom_range_selected = true;
      this.selected_date_range = 'custom_reselect';
    },
    //Trigger Filter Set and Chart re-rendering
    applyFilterOnChart() {
      this.dropdown_store.custom_date_range = this.custom_date_range;
      const paramsData = {
        start_date: this.custom_date_range.from.replace(/\//g, '-'),
        end_date: this.custom_date_range.to.replace(/\//g, '-'),
        selected_micro_service: this.selected_micro_service,
        time_bucket: this.selected_time_group,
      };

      const event = new CustomEvent('apply_filter_on_' + this.tab, {
        detail: paramsData,
      });
      document.dispatchEvent(event);
    },
    //Trigger Filter Clearing and Chart re-rendering
    clearFilterOnChart() {
      this.selected_date_range = '';
      this.custom_date_range = { from: '', to: '' };
      this.custom_range_selected = false;
      this.selected_micro_service = null;
      this.selected_time_group = '';
      const event = new CustomEvent('apply_filter_on_' + this.tab, {
        detail: { enable_all_orgs: false },
      });
      document.dispatchEvent(event);
    },
  },

  setup() {
    const dropdown_store = useDropdownStore();
    const { user_list_loading, usersList, microservice_list } =
      storeToRefs(dropdown_store);

    return {
      custom_date_range: ref({ from: '', to: '' }),
      selected_date_range: ref(''),
      selected_date_range_prev: ref('30'),
      show_calender: ref(false),

      user_list_loading,
      dropdown_store,
      custom_range_selected: ref(false),
      microservice_list,
    };
  },
});
</script>
