<!--vbase-->
<template>
  <div class="container page-height-limit">
    <div>{{ $t('business_view_text') }}</div>
    <div class="row q-col-gutter-md">
      <div class="col-12 col-md-12">
        <q-card flat bordered class="q-pa-md" id="chart-container1">
          <div id="chart1"></div>
        </q-card>
      </div>
    </div>

    <div class="row q-col-gutter-md mt-15">
      <div class="col-12 col-md-12">
        <q-card flat bordered class="q-pa-md" id="chart-container2">
          <div id="chart2"></div>
        </q-card>
      </div>
    </div>

    <div class="row q-col-gutter-md mt-15">
      <div class="col-12 col-md-12">
        <q-card flat bordered class="q-pa-md" id="chart-container3">
          <div id="chart3"></div>
        </q-card>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { ApiExceptions } from 'src/exceptions/index';
import { useDropdownStore } from 'src/store/main';
import ApexCharts from 'apexcharts';
import type { dynamicObj } from 'src/pages/assets';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import cache from 'src/utils/cache';
import { Dark } from 'quasar';
import { performanceLogsApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin.js';
import date from 'src/utils/date';
export default defineComponent({
  props: ['tab'],
  components: {},
  mixins: [displayFieldLabel, cache, helperMixin, date],
  beforeRouteLeave: function (to: any, from: any, next: any) {
    next();
  },
  data() {
    return {
      chartData: ref([] as any),
      chart: ref(null as any),
      darkMode: false,
      chartCount: 1,
      avgChartCounter: 1,
      businessEventHandler: null as ((event: any) => void) | null,
    };
  },
  mounted() {
    this.initView();
    if (Boolean(Dark.isActive) == true) {
      this.darkMode = true;
    } else {
      this.darkMode = false;
    }
    this.businessEventHandler = this.applyFilterOnChart.bind(this);
    document.addEventListener(
      'apply_filter_on_business_view',
      this.businessEventHandler,
    );
  },
  beforeUnmount() {
    if (this.businessEventHandler) {
      document.removeEventListener(
        'apply_filter_on_business_view',
        this.businessEventHandler,
      );
    }
  },
  methods: {
    initView() {
      this.prepareAndRenderChart({});
    },
    //Call Data Apis and Render Chart
    async prepareAndRenderChart(paramsData: any) {
      this.showLoading();
      await this.prepareStatusMetricsSummary(paramsData);
      const updatedParams = { ...paramsData };
      updatedParams.include_all_orgs = false;
      await this.prepareStatusMetricsSummary(updatedParams);
    },
    //Clear Chart containers
    clearChart() {
      for (let i = 1; i <= this.chartCount; i++) {
        var chart = document.getElementById('chart' + i);
        if (chart) {
          chart.remove();
        }
        var chart_container = document.getElementById('chart-container' + i);
        if (chart_container) {
          chart_container.innerHTML = '<div id="chart' + i + '"></div>';
        }
      }
      this.avgChartCounter = 1;
      this.chartCount = 0;
    },
    //Binded function to filters in parent components
    applyFilterOnChart(event: any) {
      this.clearChart();
      this.prepareAndRenderChart(event.detail);
    },
    //Function to render Status Metrics Data
    async prepareStatusMetricsSummary(paramsData: any) {
      try {
        const response =
          await performanceLogsApiService.getStatusMetricsSummary(paramsData);
        if (response.success == false) {
          throw response;
        }

        //Average Duration
        let graphKey = 'average_duration';
        if (paramsData.hasOwnProperty('include_all_orgs')) {
          graphKey = 'average_duration_for_all_other_orgs';
          this.chartData[graphKey] = this.chartData['average_duration'];
        } else {
          this.chartData['average_duration'] = response.avg_duration;
        }
        //Hardcoded list for sorting
        let hardCodedListForSorting = [
          'avg_validating_to_ready',
          'avg_ready_to_validated',
          'avg_validated_to_approved',
          'avg_second_approval_to_approved',
          'avg_approved_to_finished',
        ];
        // Create a map from label to data value for easy lookup
        const dataMap: any = {};
        response.avg_duration.labels.forEach(
          (label: string | number, idx: string | number) => {
            dataMap[label] = response.avg_duration.data[idx];
          },
        );

        // Now build sorted arrays
        const sortedData: number[] = [];
        hardCodedListForSorting.forEach((label) => {
          if (label in dataMap) {
            sortedData.push(dataMap[label]);
          }
        });
        hardCodedListForSorting = hardCodedListForSorting.map(
          (labelStr: string) => this.$t(labelStr),
        );

        //Set corresponding data based on dynamic key
        this.chartData[graphKey].data = sortedData;
        this.chartData[graphKey].labels = hardCodedListForSorting;
        this.chartData[graphKey].title = this.$t(graphKey);

        this.renderChart(
          this.chartData[graphKey],
          'bar',
          this.avgChartCounter,
          false,
          false,
        );
        this.avgChartCounter += 1;

        if (paramsData.hasOwnProperty('include_all_orgs')) {
          return;
        }

        //Status Execution
        this.chartData['status_min_max'] = {};
        const categories = [];
        const minValues = [];
        const maxValues = [];
        for (const [key, value] of Object.entries(
          response.status_execution.data[0].status_min_max,
        )) {
          const val = value as { min: number; max: number };
          categories.push(this.$t(key));
          minValues.push(val.min);
          maxValues.push(val.max);
        }
        this.chartData['status_min_max'] = {
          data: [
            { name: this.$t('minimun'), data: minValues },
            { name: this.$t('maximum'), data: maxValues },
          ],
          labels: categories,
        };
        this.chartData['status_min_max'].title = this.$t('service_summary');
        this.renderChart(
          this.chartData['status_min_max'],
          'bar',
          3,
          true,
          true,
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      }
    },
    //Render Chart with required options
    renderChart(
      chart_data: any,
      chart_type: string,
      chart_index: number,
      isMultiChart = false,
      isTrend = false,
    ) {
      try {
        if (!this.chartData) {
          return;
        }

        this.chartCount += 1;
        var options = {
          chart: {
            type: chart_type,
            height: 400,
          },
          theme: {
            mode: this.darkMode ? 'dark' : 'light',
          },
          plotOptions: {
            bar: {
              horizontal: false,
            },
          },
          xaxis: {
            categories: chart_data.labels,
            labels: {
              style: {
                colors: this.darkMode ? '#FFFFFF' : '#000000',
              },
            },
          },
          yaxis: {
            title: {
              text: this.$t('time_yaxis_label'),
            },
            labels: {
              formatter: (val: number) => this.formatSecondsToHoursMinutes(val),
            },
          },
          dataLabels: {
            enabled: true,
            formatter: (val: number, opts: any) => {
              // Optional: Only show label on line series in mixed charts
              const seriesType =
                opts?.w?.config?.series?.[opts.seriesIndex]?.type;
              return chart_type === 'bar' && seriesType === 'line'
                ? ''
                : this.formatSecondsToHoursMinutes(Number(val.toFixed(2)));
            },
            style: {
              fontWeight: 200,
              colors: this.darkMode ? ['#FFFFFF'] : ['#000000'], //D3D3D3
            },
          },
          series: isMultiChart
            ? chart_data.data
            : [
                {
                  data: chart_data.data,
                  name: chart_data.title,
                  type: chart_type,
                },
              ],
          title: {
            text: chart_data.title,
          },
          labels: chart_data.labels,
          tooltip: {
            y: {
              formatter: (val: number) =>
                this.formatSecondsToHoursMinutes(Number(val.toFixed(2))),
            },
          },
          stroke: {},
        };

        if (!isTrend && chart_type === 'bar') {
          options.series.push({
            type: 'line',
            data: chart_data.data,
            name: chart_data.title,
          });
          options.stroke = { width: [0, 2] };
        }

        if (document.querySelector('#chart' + chart_index) !== null) {
          this.chart = new ApexCharts(
            document.querySelector('#chart' + chart_index),
            options,
          );
          this.chart.render();
          this.hideLoading();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      }
    },
  },
});
</script>
